94	        }
95	        this.paragraphLines.push(line.trim());
96	    }
97	    actionHandlers = {
98	        blank: (_lines, i) => {
99	            this.flushParagraph();
100	            return i;
101	        },
102	        heading: (_lines, i, line) => {
103	            this.flushParagraph();
104	            this.currentHeading = parseHeading(line);
105	            return i;
106	        },
107	        table: (_lines, i) => {
108	            this.flushParagraph();
109	            return i;
110	        },
111	        "list-item": (lines, i) => {
112	            this.flushParagraph();
113	            const itemStartLine = i + 1;
114	            const listItem = readListItemLines(lines, i);
115	            this.pushListItemStatement(listItem.combined, itemStartLine);
116	            return listItem.endIndex;
117	        },
118	        paragraph: (_lines, i, line) => {
119	            this.appendParagraphLine(line, i + 1);
120	            return i;
121	        },
122	    };
123	    /** Processes the line at index `i`; returns the index the outer loop should resume from (before its own `i++`). */
124	    processLine(lines, i) {
125	        const line = lines[i];
126	        if (/^\s*```/.test(line)) {
127	            this.flushParagraph();
128	            this.inFence = !this.inFence;
129	            return i;
130	        }
131	        if (this.inFence) {
