1	/**
2	 * test-imports-its-subject — a `*.test.ts` file must load the real thing it
3	 * tests: a first-party module, or (for a suite whose subject is an artifact
4	 * rather than code) the file itself, read from disk. Never a copy.
5	 *
6	 * Written after `memory-lifecycle.test.ts` was found importing only vitest and
7	 * then defining its own copy of the function it claimed to test, under the
8	 * comment "(copied from memory-lifecycle.ts)". Eleven scoring tests and three
9	 * parsing tests were green against re-implementations, with fourteen spec
10	 * anchors reporting those statements covered. A change to production code could
11	 * not have failed any of them.
12	 *
13	 * A `[validated by]` link proves a test EXISTS. This is the cheapest available
14	 * proof that the test also RUNS the thing.
15	 *
16	 * Deliberately not checked: whether the imported binding is actually called. A
17	 * test can legitimately import a type-adjacent helper and exercise the subject
18	 * indirectly, and chasing that needs type information this rule does not have.
19	 * The bar here is "the real subject is loaded", which is exactly the bar the
20	 * copy failed.
21	 *
22	 * First-party means a relative path, or a package under one of the npm scopes
23	 * named in `firstPartyScopes` (default `[]`, e.g. `["@re-cinq"]` for a
24	 * monorepo whose workspace packages a suite may reach through a barrel).
25	 */
26	/** Suites that drive a system rather than one module, so no subject is implied. */
27	const EXEMPT_SUFFIXES = [
28	    ".integration.test",
29	    ".acceptance.test",
30	    ".e2e.test",
31	    ".contract.test",
32	];
33	/** The same exemption spelled as a directory, which is how lore-api spells it. */
34	const EXEMPT_DIRS = ["integration-tests"];
35	/** Accepts a scope with or without its trailing slash: `@org` and `@org/`. */
36	function isUnderScope(source, scopes) {
37	    return scopes.some((scope) => {
38	        const prefix = scope.endsWith("/") ? scope : `${scope}/`;
39	        return source.startsWith(prefix);
40	    });
41	}
42	/** `/a/b/scoring.test.ts` → `scoring`; null when this is not a test file. */
43	function subjectOf(filename) {
44	    const segments = filename.split(/[/\\]/);
45	    const base = segments.pop() ?? "";
46	    const match = base.match(/^(.*)\.test\.(ts|tsx|mts|cts|js|jsx|mjs|cjs)$/);
47	    if (!match) {
48	        return null;
49	    }
50	    if (segments.some((segment) => EXEMPT_DIRS.includes(segment))) {
51	        return null;
52	    }
53	    const stem = match[1];
54	    return EXEMPT_SUFFIXES.some((s) => `${stem}.test`.endsWith(s)) ? null : stem;
55	}
56	/**
57	 * Does `source` load the real subject?
58	 *
59	 * Deliberately NOT "does it match the filename". A first cut required the test
60	 * to import the module it is named after and flagged 86 files, nearly all
61	 * legitimate: `agent-events-oversized.test.ts` tests a facet of
62	 * `agent-events.ts`, and a suite may reach its subject through a barrel or a
63	 * sibling. The property worth enforcing is the one the copy violated — that the
64	 * test loads SOME production module rather than re-implementing its subject.
65	 *
66	 * `node:fs` counts, because a suite that reads a repo file asserts on the very
67	 * artifact it names: a migration's SQL, a stylesheet's tokens, the PR template,
68	 * package.json, the source tree itself. Its subject is a file rather than a
69	 * module, so there is no module for it to import, and it is copying nothing —
70	 * which is the whole failure this rule exists to catch. Only `fs` earns this;
71	 * another builtin (`node:crypto` under a hand-rolled HMAC) is a re-implementation
72	 * wearing an import.
73	 */
74	function loadsRealSubject(source, firstPartyScopes) {
75	    // First-party: a relative path, or a package under a configured scope.
76	    // No test-runner exclusion is needed — "vitest", "node:test", "@jest/globals",
77	    // "chai" and "assert" all fail every check already, so an explicit guard for
78	    // them never changed the answer.
79	    return (source.startsWith(".") ||
80	        isUnderScope(source, firstPartyScopes) ||
81	        source === "node:fs" ||
82	        source === "fs");
83	}
84	/** The specifier a static import loads at runtime; type-only imports are erased, so null. */
85	function staticImportSource(node) {
86	    return node.importKind === "type" ? null : node.source.value;
87	}
88	/** `vi.mock(...)` then `await import("./subject.js")` is the standard shape
89	 * for testing a module with its dependencies replaced — the static import
90	 * has to be deferred, so counting only ImportDeclaration would flag every
91	 * suite that mocks anything. */
92	function dynamicImportSource(node) {
93	    const { source } = node;
94	    const isLiteralPath = source.type === "Literal" && typeof source.value === "string";
95	    return isLiteralPath ? source.value : null;
96	}
97	export default {
98	    meta: {
99	        type: "problem",
100	        docs: {
