1	import type {ChatSession} from '../types/session.js';
2	import type {ToolRegistry, ToolContext, ToolResponse} from './tools/registry.js';
3	import type {
4	  AIProvider,
5	  Message,
6	  MessageChunk,
7	  SendMessageParams,
8	  ToolCall,
9	  ToolResultContent,
10	  UsageMetadata,
11	} from '../types/ai.js';
12	import type {OutgoingMessage} from '../types/messages.js';
13	import type {PromptBuilder, PromptBuilderOptions} from '../infrastructure/builders/promptBuilder.js';
14	import type {SessionStore} from '../types/sessionStore.js';
15	import {toMessages, createContextConfig} from './conversationContext.js';
16	import type {ContextConfig} from './conversationContext.js';
17	import {
18	  shouldContinueToolLoop,
19	  collectText,
20	  buildToolCallMessages,
21	  collectToolCalls,
22	  extractStopReason,
23	  extractUsage,
24	  accumulateUsage,
25	} from './orchestratorHelpers.js';
26	import {appendEntry, commitStreamingEntries} from './entryMutations.js';
27	import {log} from '../shared/logger.js';
28	
29	const DEFAULT_MAX_TOOL_ROUNDS = 5;
30	
31	export interface OrchestratorHooks {
32	  beforeSession?: (session: ChatSession) => Promise<void>;
33	  afterSession?: (session: ChatSession) => Promise<void>;
34	  beforeUserInput?: (session: ChatSession, userMessage: string) => Promise<string>;
35	  afterUserInput?: (session: ChatSession, userMessage: string) => Promise<void>;
36	  beforeModelResponse?: (session: ChatSession, systemPrompt: string) => Promise<string>;
37	  afterModelResponse?: (session: ChatSession, responseText: string, usage?: UsageMetadata) => Promise<void>;
38	  onError?: (session: ChatSession, error: Error) => Promise<void>;
39	  /** The supported seam for an EU AI Act Art. 14 human-oversight control: fires before each known tool's executor, and a returned ToolResponse replaces the call (see docs/adding-a-tool.md); it receives the model's raw tool input and, through session, the caller's authHeaders, so a policy that logs either logs personal data and credential material; the engine asserts nothing about any policy installed here. */
40	  beforeToolCall?: (session: ChatSession, call: ToolCall) => Promise<ToolResponse | undefined>;
41	  /** Fires when the model asks for a tool round the budget refuses, after the last provider call and before afterModelResponse; a returned string reaches the user as the turn's closing text, and the engine writes none of its own (see specs/hal-engine-tool-budget/spec.md). */
42	  onToolBudgetExhausted?: (session: ChatSession, budget: ToolBudgetInfo) => Promise<string | undefined>;
43	}
44	
45	export interface ToolBudgetInfo {
46	  maxToolRounds: number;
47	  requestedTools: string[];
48	}
49	
50	type BeforeToolCall = NonNullable<OrchestratorHooks['beforeToolCall']>;
51	type OnToolBudgetExhausted = NonNullable<OrchestratorHooks['onToolBudgetExhausted']>;
52	
53	export const TOOL_BUDGET_EXHAUSTED = 'tool_budget_exhausted';
54	
55	export interface ChatOrchestrator {
56	  processMessage(session: ChatSession): Promise<string>;
57	  processMessageStream(session: ChatSession): AsyncGenerator<MessageChunk>;
58	}
59	
60	export interface ChatOrchestratorOptions {
61	  maxToolRounds?: number;
62	  contextConfig?: Partial<ContextConfig>;
63	  promptBuilderOptions?: PromptBuilderOptions;
64	  hooks?: OrchestratorHooks;
65	  sessionStore?: SessionStore;
66	}
67	
68	interface ToolExecutionResult {
69	  clientMessages: OutgoingMessage[];
70	  suppressOutput: boolean;
71	}
72	export function createChatOrchestrator(
73	  provider: AIProvider,
74	  promptBuilder: PromptBuilder,
75	  toolRegistry?: ToolRegistry,
76	  options?: ChatOrchestratorOptions
77	): ChatOrchestrator {
78	  const maxToolRounds = normalizeToolRounds(options?.maxToolRounds);
79	  const contextConfig = createContextConfig(options?.contextConfig);
80	  const toolInstructions = toolRegistry?.getPromptInstructions();
81	  const baseSystemPrompt = promptBuilder.build({...options?.promptBuilderOptions, toolInstructions});
82	  const tools = toolRegistry?.getDefinitions();
83	  const hooks = options?.hooks;
84	  const sessionStore = options?.sessionStore;
85	
86	  return {
87	    async processMessage(session: ChatSession): Promise<string> {
88	      return collectText(this.processMessageStream(session));
89	    },
90	
91	    async *processMessageStream(session: ChatSession): AsyncGenerator<MessageChunk> {
92	      try {
93	        if (hooks?.beforeSession) await hooks.beforeSession(session);
94	
95	        let userMessage = lastUserContent(session);
96	
97	        if (hooks?.beforeUserInput) {
98	          userMessage = await rewriteUserMessage(session, userMessage, hooks.beforeUserInput);
99	        }
100	
101	        if (hooks?.afterUserInput) await hooks.afterUserInput(session, userMessage);
102	
103	        const systemPrompt = hooks?.beforeModelResponse
104	          ? await hooks.beforeModelResponse(session, baseSystemPrompt)
105	          : baseSystemPrompt;
106	
107	        const messages: Message[] = toMessages(session.entries, contextConfig);
108	        let lastUsage: UsageMetadata | undefined;
109	        let responseText = '';
110	
111	        // Bounded by the budget gate below, not the header: maxToolRounds executed rounds, maxToolRounds + 1 provider calls.
112	        for (let round = 0; ; round++) {
113	          log.info('orchestrator', 'starting round', {round});
114	          const pendingToolCalls: ToolCall[] = [];
115	
116	          const outcome = yield* streamRound(provider, {messages, systemPrompt, tools}, pendingToolCalls);
117	          responseText += outcome.text;
118	          lastUsage = accumulateUsage(lastUsage, outcome.usage);
119	
120	          if (!shouldContinueToolLoop(outcome.stopReason, pendingToolCalls, toolRegistry)) break;
121	          if (budgetSpent(round, maxToolRounds, pendingToolCalls)) {
122	            const budget = {maxToolRounds, requestedTools: pendingToolCalls.map(tc => tc.name)};
123	            responseText += yield* closeExhaustedTurn(session, budget, hooks?.onToolBudgetExhausted);
124	            break;
125	          }
126	
127	          log.info('orchestrator', 'executing tools', {tools: pendingToolCalls.map(tc => tc.name)});
128	          const {clientMessages, suppressOutput} = await executeToolCalls(
129	            pendingToolCalls,
130	            messages,
131	            session,
132	            toolCallRunner(toolRegistry!, session, hooks?.beforeToolCall)
133	          );
134	          log.info('orchestrator', 'tool execution complete', {
135	            clientMessageCount: clientMessages.length,
136	            clientMessageTypes: clientMessages.map(m => m.type),
137	            suppressOutput,
138	          });
139	
140	          if (clientMessages.length > 0) {
141	            yield {type: 'tool_result' as const, clientMessages};
142	          }
143	
144	          if (suppressOutput) {
145	            yield {type: 'suppress_output' as const};
146	          }
147	        }
148	
149	        if (hooks?.afterModelResponse) await hooks.afterModelResponse(session, responseText, lastUsage);
150	      } catch (error) {
151	        if (hooks?.onError && error instanceof Error) {
152	          await hooks.onError(session, error);
153	        }
154	        throw error;
155	      } finally {
156	        // Before both: a provider that threw mid-stream leaves an entry open, and nothing should persist it that way.
157	        commitStreamingEntries(session);
158	        try {
159	          if (hooks?.afterSession) await hooks.afterSession(session);
160	        } finally {
161	          await saveSession(sessionStore, session);
162	        }
163	      }
164	    },
165	  };
166	}
167	
168	// A negative budget means no tool rounds; a non-finite one, NaN included, falls back to the default rather than never ending.
169	function normalizeToolRounds(value: number | undefined): number {
170	  if (value === undefined || !Number.isFinite(value)) return DEFAULT_MAX_TOOL_ROUNDS;
171	  return Math.max(0, Math.floor(value));
172	}
173	
174	// Gates execution, not the provider call: a round nobody can read is never run, and the call that read the last one already has.
175	function budgetSpent(round: number, maxToolRounds: number, pendingToolCalls: ToolCall[]): boolean {
176	  if (round < maxToolRounds) return false;
177	  log.warn('orchestrator', 'tool budget exhausted', {
178	    maxToolRounds,
179	    requestedTools: pendingToolCalls.map(tc => tc.name),
180	  });
181	  return true;
182	}
183	
184	// The stop always follows the text: the round's own stop already committed its entry, and a bare text chunk would open one never committed.
185	async function* closeExhaustedTurn(
186	  session: ChatSession,
187	  budget: ToolBudgetInfo,
188	  hook?: OnToolBudgetExhausted
189	): AsyncGenerator<MessageChunk, string> {
190	  const sentence = (hook ? await hook(session, budget) : undefined) ?? '';
191	  if (sentence !== '') yield {type: 'text', text: sentence};
192	  yield {type: 'stop', stopReason: TOOL_BUDGET_EXHAUSTED};
193	  return sentence;
194	}
195	
196	interface RoundOutcome {
197	  stopReason: string;
198	  text: string;
199	  usage?: UsageMetadata;
200	}
201	
202	// `yield*` in the caller evaluates to this return, so the round's totals come back as data.
203	async function* streamRound(
204	  provider: AIProvider,
205	  request: SendMessageParams,
206	  pendingToolCalls: ToolCall[]
207	): AsyncGenerator<MessageChunk, RoundOutcome> {
208	  let stopReason = '';
209	  let text = '';
210	  let usage: UsageMetadata | undefined;
211	
212	  for await (const chunk of provider.sendMessage(request)) {
213	    yield chunk;
214	    collectToolCalls(chunk, pendingToolCalls);
215	    stopReason = extractStopReason(chunk) ?? stopReason;
216	    usage = extractUsage(chunk) ?? usage;
217	    if (chunk.type === 'text') text += chunk.text;
218	  }
219	
220	  return {stopReason, text, usage};
221	}
222	
223	// A changed message is also written back to the session's last user entry.
224	async function rewriteUserMessage(
225	  session: ChatSession,
226	  userMessage: string,
227	  hook: (session: ChatSession, userMessage: string) => Promise<string>
228	): Promise<string> {
229	  const modified = await hook(session, userMessage);
230	  if (modified === userMessage) return userMessage;
231	
232	  updateLastUserContent(session, modified);
233	  return modified;
234	}
235	
236	function lastUserContent(session: ChatSession): string {
237	  for (let i = session.entries.length - 1; i >= 0; i--) {
238	    const entry = session.entries[i];
239	    if (entry.role === 'user') return entry.content;
240	  }
241	  return '';
242	}
243	
244	function updateLastUserContent(session: ChatSession, content: string): void {
245	  for (let i = session.entries.length - 1; i >= 0; i--) {
246	    const entry = session.entries[i];
247	    if (entry.role === 'user') {
248	      entry.content = content;
249	      return;
250	    }
251	  }
252	}
253	
254	// One runner per round: the policy sees each known call before its executor, and an unknown name keeps the registry's own path.
255	function toolCallRunner(toolRegistry: ToolRegistry, session: ChatSession, beforeToolCall?: BeforeToolCall) {
256	  const context: ToolContext = {
257	    userId: session.userId,
258	    sessionId: session.sessionId,
259	    workspaceId: session.workspaceId,
260	    authHeaders: session.authHeaders,
261	  };
262	
263	  return async (tc: ToolCall): Promise<ToolResponse> => {
264	    const declined =
265	      beforeToolCall && toolRegistry.has(tc.name) ? await consultPolicy(beforeToolCall, session, tc) : undefined;
266	    return declined ?? toolRegistry.execute(tc.name, tc.input, context);
267	  };
268	}
269	
270	// A throwing policy declines its call rather than failing the turn: every tool_use must still be answered.
271	async function consultPolicy(
272	  policy: BeforeToolCall,
273	  session: ChatSession,
274	  tc: ToolCall
275	): Promise<ToolResponse | undefined> {
276	  try {
277	    return await policy(session, tc);
278	  } catch (error) {
279	    log.warn('orchestrator', 'beforeToolCall threw, so the call is declined', {
280	      tool: tc.name,
281	      errorType: error instanceof Error ? error.name : typeof error,
282	    });
283	    return {result: `The ${tc.name} call was declined and not performed.`};
284	  }
285	}
286	
287	async function executeToolCalls(
288	  pendingToolCalls: ToolCall[],
289	  messages: Message[],
290	  session: ChatSession,
291	  runToolCall: (tc: ToolCall) => Promise<ToolResponse>
292	): Promise<ToolExecutionResult> {
293	  messages.push(buildToolCallMessages(pendingToolCalls));
294	
295	  const responses = await Promise.all(
296	    pendingToolCalls.map(async tc => {
297	      const response = await runToolCall(tc);
298	      return {tc, response};
299	    })
300	  );
301	
302	  const toolResults: ToolResultContent[] = responses.map(({tc, response}) => ({
303	    type: 'tool_result' as const,
304	    toolUseId: tc.id,
305	    content: response.result,
306	  }));
307	  messages.push({role: 'user', content: toolResults});
308	
309	  const rawClientMessages = responses.flatMap(({response}) => response.clientMessages ?? []);
310	
311	  return {
312	    clientMessages: assignEntryIndices(rawClientMessages, session),
313	    suppressOutput: responses.some(({response}) => response.suppressAssistantResponse === true),
314	  };
315	}
316	
